import subprocess

# Example of running a safe subprocess command
def safe_ps_command():
    try:
        # Using a fixed command to avoid injection
        result = subprocess.run(['ps', 'aux'], capture_output=True, text=True)
        print(result.stdout)
    except subprocess.CalledProcessError as e:
        print(f"An error occurred: {e}")

safe_ps_command()
